const express = require('express');
const Typesense = require('typesense');
const fs = require('fs');
const path = require('path');

// Read API key from file or default
let apiKey = 'xyz';
try {
  apiKey = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();
} catch (e) {
  // use default
}

const typesense = new Typesense.Client({
  nodes: [
    {
      host: '127.0.0.1',
      port: '8108',
      protocol: 'http',
    },
  ],
  apiKey: apiKey,
  connectionTimeoutSeconds: 5,
});

const COLLECTION_NAME = 'catalog';

// Schema for the catalog collection
const catalogSchema = {
  name: COLLECTION_NAME,
  fields: [
    { name: 'name', type: 'string' },
    { name: 'category', type: 'string' },
    { name: 'price', type: 'float' },
  ],
};

async function setupCollection() {
  try {
    // Delete if exists
    try {
      await typesense.collections(COLLECTION_NAME).delete();
      console.log('Deleted existing collection');
    } catch (e) {
      // collection doesn't exist, that's fine
    }

    // Create collection
    await typesense.collections().create(catalogSchema);
    console.log('Created collection');

    // Import seed data
    const seedPath = path.join(__dirname, 'catalog-seed.json');
    const products = JSON.parse(fs.readFileSync(seedPath, 'utf8'));
    await typesense.collections(COLLECTION_NAME).documents().import(products);
    console.log(`Imported ${products.length} products`);
  } catch (e) {
    console.error('Setup error:', e.message);
  }
}

const app = express();

// Serve static HTML
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'index.html'));
});

// Search API
app.get('/api/search', async (req, res) => {
  const q = req.query.q || '';

  try {
    const searchParams = {
      q: q,
      query_by: 'name',
      per_page: 250,
    };

    const searchResult = await typesense.collections(COLLECTION_NAME).documents().search(searchParams);

    const found = searchResult.found || 0;
    const hits = (searchResult.hits || []).map((h) => ({
      id: h.document.id,
      name: h.document.name,
    }));

    let suggestions = [];
    if (found === 0) {
      // Get trending queries to suggest
      try {
        const trending = await getTrendingQueries();
        suggestions = trending.map((t) => t.q);
      } catch (e) {
        // ignore
      }
    }

    res.json({
      query: q,
      found: found,
      hits: hits,
      suggestions: suggestions,
    });
  } catch (e) {
    console.error('Search error:', e.message);
    res.json({
      query: q,
      found: 0,
      hits: [],
      suggestions: [],
    });
  }
});

async function getTrendingQueries() {
  try {
    // Use Typesense v26 search analytics endpoint
    // The analytics endpoint returns popular queries
    const result = await typesense.analytics.rules().retrieve();
    // The analytics rules endpoint may not be what we need.
    // Let's try the analytics events endpoint
    console.log('Analytics rules:', JSON.stringify(result));
  } catch (e) {
    console.log('Analytics rules error:', e.message);
  }

  try {
    // Typesense v26 has GET /analytics/queries endpoint for popular queries
    // Using the raw API call
    const result = await typesense.analytics.queries().retrieve();
    console.log('Analytics queries:', JSON.stringify(result));
    return [];
  } catch (e) {
    console.log('Analytics queries error:', e.message);
  }

  return [];
}

// Trending API
app.get('/api/trending', async (req, res) => {
  try {
    const trending = await getTrendingQueries();
    res.json({ trending: trending });
  } catch (e) {
    console.error('Trending error:', e.message);
    res.json({ trending: [] });
  }
});

// Start server
async function start() {
  await setupCollection();

  app.listen(3000, () => {
    console.log('Server running on http://127.0.0.1:3000');
  });
}

start().catch(console.error);

